#!/usr/bin/env bash
# Copies the Kubernetes ZeedLogic dashboards from a zeedlogic-microservices checkout into this repository.
# The source of truth is deploy/shared/grafana-dashboards/k8s/ there (generated by make-k8s-dashboards.py).
#   ./grafana/sync-zeedlogic-dashboards.sh ~/zeedlogic-microservices
set -euo pipefail
SRC="${1:?path to the zeedlogic-microservices checkout}/deploy/shared/grafana-dashboards/k8s"
DST="$(cd "$(dirname "$0")" && pwd)/dashboards/zeedlogic"
mkdir -p "$DST"
cp "$SRC"/zeedlogic-k8s-*.json "$DST"/
ls -l "$DST"
